/**
 * `repr()` for the value graph bencoder returns: int, bytes, list, dict.
 *
 * `print(value)` uses `str(value)`, and for every one of these types
 * `str is repr` (containers always repr their members), so a single
 * implementation covers both.
 */

import { Bytes } from './bytestring.mjs';
import { PyDict } from './pydict.mjs';
import { pyIntRepr } from './pyint.mjs';

/**
 * `repr(bytes)`, following CPython's `bytes_repr`:
 *   * the literal is single-quoted unless it contains `'` and no `"`,
 *   * the active quote and backslash are backslash-escaped,
 *   * tab / newline / carriage return get their short escapes,
 *   * every other byte outside the printable ASCII range becomes `\xNN`.
 */
export function pyBytesRepr(value) {
  const raw = value.raw;
  const quote = raw.includes("'") && !raw.includes('"') ? '"' : "'";

  let body = '';
  for (let index = 0; index < raw.length; index += 1) {
    const ch = raw[index];
    const code = raw.charCodeAt(index);
    if (ch === quote || ch === '\\') body += `\\${ch}`;
    else if (code === 0x09) body += '\\t';
    else if (code === 0x0a) body += '\\n';
    else if (code === 0x0d) body += '\\r';
    else if (code < 0x20 || code >= 0x7f) body += `\\x${code.toString(16).padStart(2, '0')}`;
    else body += ch;
  }
  return `b${quote}${body}${quote}`;
}

export function pyRepr(value) {
  if (typeof value === 'bigint') return pyIntRepr(value);
  if (value instanceof Bytes) return pyBytesRepr(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof PyDict) {
    const body = value
      .entries()
      .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
      .join(', ');
    return `{${body}}`;
  }
  return String(value);
}

/** `str(value)` — identical to `repr` for every type reachable here. */
export const pyStr = pyRepr;

/**
 * `Bytes` — an immutable byte sequence modelled on CPython's `bytes`.
 *
 * Representation: a plain JS string in which every code unit holds one byte
 * value (0..255). The source program only ever produces bytes via
 * `str.encode('ascii')`, so in practice every code unit is < 128. Keeping the
 * payload in a string lets us reuse JS string search/slice primitives and the
 * regular-expression engine directly, which is exactly what CPython's
 * `re.match(b'...', x)` does on the bytes side.
 */

export class Bytes {
  /** @param {string} raw one code unit per byte */
  constructor(raw) {
    /** @type {string} */
    this.raw = raw;
    Object.freeze(this);
  }

  /** `len(x)` */
  get length() {
    return this.raw.length;
  }

  /** `x[i]` — the integer byte value, or `undefined` when out of range. */
  byteAt(index) {
    if (index < 0 || index >= this.raw.length) return undefined;
    return this.raw.charCodeAt(index);
  }

  /** `x.startswith(prefix)` where `prefix` is given as a JS string. */
  startsWith(prefix) {
    return this.raw.startsWith(prefix);
  }

  /** `x[start:]` with Python's clamping semantics for non-negative `start`. */
  sliceFrom(start) {
    if (start <= 0) return this;
    if (start >= this.raw.length) return EMPTY_BYTES;
    return new Bytes(this.raw.slice(start));
  }

  /**
   * `x[start:start + count]`.
   *
   * `count` may be a bigint far beyond the sequence length — bencoded length
   * prefixes are arbitrary-precision integers and CPython simply clamps the
   * slice, which is why `b'9:value'` decodes to `b'value'`.
   */
  sliceCount(start, count) {
    const available = BigInt(Math.max(this.raw.length - start, 0));
    const take = count > available ? available : count;
    if (take <= 0n) return EMPTY_BYTES;
    return new Bytes(this.raw.slice(start, start + Number(take)));
  }

  /** `x[start + count:]`, clamped the same way as {@link sliceCount}. */
  sliceAfter(start, count) {
    const available = BigInt(Math.max(this.raw.length - start, 0));
    const take = count > available ? available : count;
    return this.sliceFrom(start + Number(take));
  }

  equals(other) {
    return other instanceof Bytes && other.raw === this.raw;
  }
}

export const EMPTY_BYTES = new Bytes('');

/** True when the byte is an ASCII decimal digit, i.e. `chr(b).isdigit()`. */
export function isAsciiDigitByte(byte) {
  return byte !== undefined && byte >= 0x30 && byte <= 0x39;
}
=== exceptions (frames/traceback) ===
/**
 * Python-flavoured exception objects plus the traceback renderer.
 *
 * The reference program is a frozen (PyInstaller) build of `test4.py`, so an
 * uncaught exception produces:
 *
 *   Traceback (most recent call last):
 *     File "test4.py", line 8, in <module>
 *       result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string
 *                ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *     File "bencoder.py", line 93, in decode
 *     File "bencoder.py", line 88, in decode_first
 *   AssertionError
 *
 * Frames inside the frozen library have no source line available, so only the
 * `File ...` line is emitted for them. Exit status for an uncaught exception
 * is 1.
 */

import { formatSourceLines, getLine } from './linecache.mjs';

export class PyException extends Error {
  constructor(typeName, detail) {
    super(detail == null ? typeName : `${typeName}: ${detail}`);
    this.typeName = typeName;
    this.detail = detail == null ? null : detail;
    /** @type {Array<{file: string, line: number, func: string}>} */
    this.pyFrames = [];
  }

  /** Final traceback line: `TypeError: Malformed input.` or bare `AssertionError`. */
  get exceptionLine() {
    return this.detail == null ? this.typeName : `${this.typeName}: ${this.detail}`;
  }
}

export class PyIndexError extends PyException {
  constructor(detail) {
    super('IndexError', detail);
  }
}

export class PyAttributeError extends PyException {
  constructor(detail) {
    super('AttributeError', detail);
  }
}

export class PyTypeError extends PyException {
  constructor(detail) {
    super('TypeError', detail);
  }
}

export class PyAssertionError extends PyException {
  constructor() {
    super('AssertionError', null);
  }
}

export class PyRecursionError extends PyException {
  constructor() {
    super('RecursionError', 'maximum recursion depth exceeded');
  }
}

export class PyUnicodeEncodeError extends PyException {
  constructor(detail) {
    super('UnicodeEncodeError', detail);
  }
}

/** Record a caller frame while an exception propagates outwards. */
export function pushFrame(error, frame) {
  if (error instanceof PyException) error.pyFrames.unshift(frame);
  return error;
}

/** The `<module>` frame of test4.py, line 8. */
const MODULE_FILENAME = 'test4.py';
const MODULE_LINENO = 8;

/**
 * CPython 3.11+ underlines the sub-expression that raised. Two spans occur
 * here, given as the 0-based byte columns the code object records for line 8
 * (`result = bencoder.decode(args.a.encode('ascii'))  # ...`):
 * the whole `bencoder.decode(...)` call, and the inner `args.a.encode('ascii')`
 * call when the ASCII encode itself fails.
 */
export const CARET_DECODE_CALL = 'decode-call';
export const CARET_ENCODE_CALL = 'encode-call';

const CARET_SPANS = {
  [CARET_DECODE_CALL]: { colno: 9, endColno: 48 },
  [CARET_ENCODE_CALL]: { colno: 25, endColno: 47 },
};

/** CPython's `traceback._RECURSIVE_CUTOFF`. */
const RECURSIVE_CUTOFF = 3;

function formatFrames(frames) {
  const lines = [];
  let lastKey = null;
  let count = 0;

  const flush = () => {
    if (count > RECURSIVE_CUTOFF) {
      const extra = count - RECURSIVE_CUTOFF;
      lines.push(`  [Previous line repeated ${extra} more time${extra > 1 ? 's' : ''}]`);
    }
  };

  for (const frame of frames) {
    const key = `${frame.file}:${frame.line}:${frame.func}`;
    if (key !== lastKey) {
      flush();
      lastKey = key;
      count = 0;
    }
    count += 1;
    if (count > RECURSIVE_CUTOFF) continue;
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.func}`);
    if (frame.caretSpan !== undefined) {
      // Frames inside the frozen library have no readable source; the script
      // frame does, provided ./test4.py is where the process was started.
      lines.push(...formatSourceLines(getLine(frame.file, frame.line), frame.caretSpan));
    }
  }
  flush();
  return lines;
}

/**
 * Render the full traceback text (including the trailing newline) for an
 * exception escaping line 8 of test4.py.
 */
export function formatTraceback(error, caretSpan) {
  const frames = [
    {
      file: MODULE_FILENAME,
      line: MODULE_LINENO,
      func: '<module>',
      caretSpan: CARET_SPANS[caretSpan],
    },
    ...(error instanceof PyException ? error.pyFrames : []),
  ];

  const lines = ['Traceback (most recent call last):', ...formatFrames(frames)];
  lines.push(error instanceof PyException ? error.exceptionLine : String(error));
  // The frozen-executable epilogue; the number is the reporting process id.
  lines.push(`[PYI-${process.pid}:ERROR] Failed to execute script 'test4' due to unhandled exception!`);
  return `${lines.join('\n')}\n`;
}

